using sk_bisect::bisect_raw_ptr;

template <typename T, auto Traits>
struct sk_is_trivially_relocatable<sk_bisect::bisect_raw_ptr<T, Traits>>
        : std::true_type {};

namespace std {

// Override so set/map lookups do not create extra bisect_raw_ptr. This also allows dangling pointers to be
// used for lookup.
template <typename T, auto Traits> struct less<bisect_raw_ptr<T, Traits>> {
    using is_transparent = void;

    bool operator()(const bisect_raw_ptr<T, Traits>& lhs, const bisect_raw_ptr<T, Traits>& rhs) const {
        return lhs < rhs;
    }
    bool operator()(T* lhs, const bisect_raw_ptr<T, Traits>& rhs) const { return lhs < rhs; }
    bool operator()(const bisect_raw_ptr<T, Traits>& lhs, T* rhs) const { return lhs < rhs; }
};

template <typename T, auto Traits> struct hash<bisect_raw_ptr<T, Traits>> {
    typedef bisect_raw_ptr<T, Traits> argument_type;
    typedef std::size_t result_type;
    result_type operator()(argument_type const& ptr) const { return hash<T*>()(ptr.get()); }
};

// Define for cases where bisect_raw_ptr<T> holds a pointer to an array of type T. This is consistent with
// definition of std::iterator_traits<T*>. Algorithms like std::binary_search need that.
template <typename T, auto Traits> struct iterator_traits<bisect_raw_ptr<T, Traits>> {
    using difference_type = ptrdiff_t;
    using value_type = std::remove_cv_t<T>;
    using pointer = T*;
    using reference = T&;
    using iterator_category = std::random_access_iterator_tag;
};

// Specialize std::pointer_traits. The latter is required to obtain the underlying raw pointer in
// the std::to_address(pointer) overload. Implementing the pointer_traits is the standard blessed
// way to customize `std::to_address(pointer)` in C++20 [1].
//
// [1] https://wg21.link/pointer.traits.optmem
template <typename T, auto Traits> struct pointer_traits<bisect_raw_ptr<T, Traits>> {
    using pointer = bisect_raw_ptr<T, Traits>;
    using element_type = T;
    using difference_type = ptrdiff_t;

    template <typename U> using rebind = ::bisect_raw_ptr<U, Traits>;

    static constexpr pointer pointer_to(element_type& r) noexcept { return pointer(&r); }
    static constexpr element_type* to_address(pointer p) noexcept { return p.get(); }
};

}  // namespace std

